#include <iostream>

int main() {
    int totalPoints{7};
    int participantCount{2};
    // Protective scaffold: domain checks precede the division.
    if (totalPoints < 0 || totalPoints > 1000 || participantCount < 1 || participantCount > 1000) {
        std::cout << "invalid\n";
        return 0;
    }
    double average = static_cast<double>(totalPoints) / participantCount;
    std::cout << "average=" << average << '\n';
    return 0;
}

