blockPracticum.referenceCode:
#include <iostream>

int main() {
    const long long itemCount{3};
    const long long unitPriceCents{125};
    const long long deliveryCents{50};
    if (itemCount < 1 || itemCount > 1000 || unitPriceCents < 0 || unitPriceCents > 100000 || deliveryCents < 0 || deliveryCents > 100000) {
        std::cout << "invalid\n";
        return 0;
    }
    long long goodsCents = itemCount * unitPriceCents;
    long long totalCents = goodsCents + deliveryCents;
    double averageCents = static_cast<double>(totalCents) / itemCount;
    std::cout << "goods_cents=" << goodsCents << '\n';
    std::cout << "total_cents=" << totalCents << '\n';
    std::cout << "average_cents=" << averageCents << '\n';
    return 0;
}
